-- Details-panel content for the places that had none.
--
-- Generated by scripts/wine-map-sources/gen-place-profiles-migration.mjs from
-- data/wine-map/place-profiles.json. Do not hand-edit: the generator resolves every grape name and
-- canonical_key against the live catalog and refuses to emit anything if one of
-- them does not resolve. That check is the point of it. A grape name the
-- catalog does not carry does not raise on insert -- the join simply matches
-- nothing and the row vanishes, leaving a place quietly short of a variety.
--
-- 2 places: germany 2.
-- 6 style rows, 12 grape rows, 2 Bereich articles,
-- 0 varieties added to the grape catalog.
--
-- Convention follows the existing region rows (germany.mosel, italy.piemonte):
-- role PRINCIPAL, permitted true, share_pct null. Planting percentages are not
-- invented -- france.champagne carries them because they are published.
--
-- NO TILE RUN. scripts/wine-map-tiles/export.mjs reads wine_places and
-- wine_place_boundaries only; grapes, styles and articles are served by
-- get_wine_place_context at request time. Nothing here changes a tile.

begin;

-- germany.baden
insert into public.wine_place_articles (wine_place_id, description, climate, soils, key_facts, editorial_status)
select id, 'Germany''s third-largest wine region at 15.142 hectares, and the one that runs furthest: roughly 400 kilometres from the Tauber in the north to Lake Constance in the south, in nine Bereiche that share little beyond the name. Above all it is Burgundy country. The Pinot family covers 9.162 hectares, 61 per cent of the region, and Baden grows more Spätburgunder and more Weißburgunder than anywhere else in Germany.', 'The warmest region in German wine, and the only one the EU places in wine-growing Zone B rather than Zone A — so its musts must reach higher Oechsle weights than the rest of the country. It lies in the lee of the Vosges, in the Rhine rift between the Black Forest and the Alsace hills, and the Kaiserstuhl counts among the warmest places in Germany. The Bodensee in the south is cooler, and later.', 'As varied as the 400-kilometre run implies. The Kaiserstuhl is an eroded volcano, volcanic rock under deep wind-blown loess, and the neighbouring Tuniberg is loess almost throughout. The Ortenau is granite and weathered granitic soil; the Markgräflerland limestone and loess; and Tauberfranken in the far north sits on Muschelkalk, the shell limestone it shares with Franken next door.', array['15.142 ha (DWI, 2025), Germany''s third-largest region', 'The only German Anbaugebiet in EU wine-growing Zone B; the other twelve are Zone A', 'Pinot varieties are 9.162 ha, 61 % of the region', 'Spätburgunder 4.765 ha and Weißburgunder 1.640 ha, the largest plantings of each in Germany', 'Nine Bereiche, 16 Großlagen and 306 Einzellagen, from the Tauber to Lake Constance', 'Badisch Rotgold, a rosé pressed from Grauburgunder and Spätburgunder together, may be made in Baden and nowhere else']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'germany.baden';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'WHITE', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'germany.baden';
