select id, 'RED', 1, 'PUBLISHED' from public.wine_places where canonical_key = 'germany.baden';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'ROSE', 2, 'PUBLISHED' from public.wine_places where canonical_key = 'germany.baden';
insert into public.wine_place_grapes (wine_place_id, grape_id, role, permitted, share_pct, local_note, editorial_status)
select p.id, g.id, 'PRINCIPAL', true, 31, 'Spätburgunder — 4.765 ha, Germany''s largest planting of it', 'PUBLISHED'
