 where p.canonical_key = 'germany.wuerttemberg' and g.name = 'Blaufränkisch';
insert into public.wine_place_grapes (wine_place_id, grape_id, role, permitted, share_pct, local_note, editorial_status)
select p.id, g.id, 'PRINCIPAL', true, 15, '1.614 ha — the everyday red of Swabia; the same grape as Alto Adige''s Schiava, but in Germany it is grown almost only here', 'PUBLISHED'
  from public.wine_places p, public.grapes g
 where p.canonical_key = 'germany.wuerttemberg' and g.name = 'Trollinger';
